import java.util.*;
public class HashTable {
    static final int SIZE = 11;
    List<int[]>[] table = new ArrayList[SIZE];
    HashTable() { for(int i=0;i<SIZE;i++) table[i]=new ArrayList<>(); }
    int hash(int key) { return key % SIZE; }
    void put(int key, int val) {
        int idx = hash(key);
        for (int[] kv : table[idx]) if (kv[0] == key) { kv[1] = val; return; }
        table[idx].add(new int[]{key, val});
    }
    Integer get(int key) {
        for (int[] kv : table[hash(key)]) if (kv[0] == key) return kv[1];
        return null;
    }
    boolean remove(int key) {
        List<int[]> bucket = table[hash(key)];
        return bucket.removeIf(kv -> kv[0] == key);
    }
}

