    for (Node* n=table[i]; n; n=n->next)if (n->key==k) {
        n->val=v;
        return;
    }
    Node* n=(Node*)malloc(sizeof(Node));
    n->key=k;
    n->val=v;
    n->next=table[i];
    table[i]=n;
}
